// === Tab: mySketch ===
let radius = 100;
const maxParticles = 2000;
let particleCount = 500;
let centerSpread = 50;
let particleSize = 5;

let particles = [];

let radiusSlider, countSlider, spreadSlider, sizeSlider;
let controlsDiv;

class Particle {
  constructor(x, y) {
    this.centerX = x;
    this.centerY = y;
    this.angle = random(TWO_PI);
    this.speed = random(0.01, 0.05);
    this.phase = random(TWO_PI);
  }

  update() {
    this.angle += this.speed;
    if (this.angle > TWO_PI) this.angle -= TWO_PI;
  }

  display() {
    let x = this.centerX + radius * cos(this.angle + this.phase);
    let y = this.centerY + radius * sin(this.angle + this.phase);
    ellipse(x, y, particleSize, particleSize);
  }
}

function setup() {
  createCanvas(1000, 800);
  noStroke();
  fill(255, 150);

  // Vytvoření kontejneru pro ovládací prvky
  controlsDiv = createDiv();
  controlsDiv.position(10, 10);
  controlsDiv.style('background-color', 'rgba(0, 0, 0, 0.6)');
  controlsDiv.style('padding', '10px');
  controlsDiv.style('border-radius', '8px');
  controlsDiv.style('color', 'white');
  controlsDiv.style('font-family', 'Arial, sans-serif');
  controlsDiv.style('width', '220px');

  // Funkce pro vytvoření popisku + slideru
  function createLabeledSlider(labelText, min, max, start, step=1) {
    let label = createP(labelText);
    label.parent(controlsDiv);
    label.style('margin', '5px 0 2px 0');
    label.style('font-weight', 'bold');
    label.style('font-size', '14px');
    let slider = createSlider(min, max, start, step);
    slider.parent(controlsDiv);
    slider.style('width', '200px');
    slider.style('margin-bottom', '10px');
    return slider;
  }

  radiusSlider = createLabeledSlider('Radius', 10, 200, radius);
  countSlider = createLabeledSlider('Particle Count', 100, maxParticles, particleCount);
  spreadSlider = createLabeledSlider('Center Spread', 0, 200, centerSpread);
  sizeSlider = createLabeledSlider('Particle Size', 1, 20, particleSize);

  initializeParticles();
}

function draw() {
  background(0);

  radius = radiusSlider.value();
  let newCount = countSlider.value();
  if (newCount !== particleCount) {
    particleCount = newCount;
  }
  let newSpread = spreadSlider.value();
  if (newSpread !== centerSpread) {
    centerSpread = newSpread;
    initializeParticles();
  }
  particleSize = sizeSlider.value();

  for (let i = 0; i < particleCount; i++) {
    particles[i].update();
    particles[i].display();
  }
}

function initializeParticles() {
  particles = [];
  for (let i = 0; i < maxParticles; i++) {
    let centerX = width / 2 + random(-centerSpread, centerSpread);
    let centerY = height / 2 + random(-centerSpread, centerSpread);
    particles.push(new Particle(centerX, centerY));
  }
}

